// Views over flattened embedded-base fields (generated). Callers get
// pointers to the real fields so reads and writes behave like Go's
// embedded-base accessors.

struct DeclarationDataRef { Symbol** symbol; };
struct ExportableDataRef { Symbol** localSymbol; };
struct LocalsContainerDataRef { SymbolTable* locals; Node** nextContainer; };
struct FlowNodeDataRef { FlowNode** flowNode; };
struct FunctionLikeDataRef { SymbolTable* locals; Node** nextContainer; NodeList** typeParameters; NodeList** parameters; Node** type; Node** fullSignature; };
struct BodyDataRef { Node** asteriskToken; Node** body; FlowNode** endFlowNode; };
struct ClassLikeDataRef { Symbol** localSymbol; ModifierList** modifiers; SymbolTable* locals; Node** nextContainer; Node** name; NodeList** typeParameters; NodeList** heritageClauses; NodeList** members; };
struct LiteralLikeDataRef { std::string* text; TokenFlags* tokenFlags; };
struct TemplateLiteralLikeDataRef { std::string* text; TokenFlags* tokenFlags; std::string* rawText; TokenFlags* templateFlags; };

