inline SubtreeFacts computeSubtreeFacts_ArrayLiteralExpression(const ArrayLiteralExpression* n) {
	return ::tsc::propagateNodeListSubtreeFacts(n->Elements, propagateSubtreeFacts);
}

inline SubtreeFacts computeSubtreeFacts_ArrowFunction(const ArrowFunction* n) {
	return ::tsc::propagateModifierListSubtreeFacts(n->modifiers) | ::tsc::propagateEraseableSyntaxListSubtreeFacts(n->TypeParameters) | ::tsc::propagateNodeListSubtreeFacts(n->Parameters, propagateSubtreeFacts) | propagateEraseableSyntaxSubtreeFacts(n->Type) | propagateEraseableSyntaxSubtreeFacts(n->FullSignature) | ::tsc::propagateSubtreeFacts(n->Body) | ifElse((n->modifierFlags()&ModifierFlagsAsync) != 0, SubtreeContainsAnyAwait, SubtreeFactsNone);
}

inline SubtreeFacts computeSubtreeFacts_AsExpression(const AsExpression* n) {
	return ::tsc::propagateSubtreeFacts(n->Expression) | SubtreeContainsTypeScript;
}

inline SubtreeFacts computeSubtreeFacts_AwaitExpression(const AwaitExpression* n) {
	return ::tsc::propagateSubtreeFacts(n->Expression) | SubtreeContainsAwait | SubtreeContainsAnyAwait | SubtreeContainsForAwaitOrAsyncGenerator;
}

inline SubtreeFacts computeSubtreeFacts_BigIntLiteral(const BigIntLiteral* n) {
	return SubtreeFactsNone;
}

inline SubtreeFacts computeSubtreeFacts_BinaryExpression(const BinaryExpression* n) {
	auto facts = ::tsc::propagateModifierListSubtreeFacts(n->modifiers) | ::tsc::propagateSubtreeFacts(n->Left) | ::tsc::propagateSubtreeFacts(n->Type) | ::tsc::propagateSubtreeFacts(n->OperatorToken) | ::tsc::propagateSubtreeFacts(n->Right) | ifElse(n->OperatorToken->kind == Kind::InKeyword && isPrivateIdentifier(n->Left), SubtreeContainsClassFields|SubtreeContainsPrivateIdentifierInExpression, SubtreeFactsNone);
	if (n->OperatorToken->kind == Kind::EqualsToken) {
	if ((isObjectLiteralExpression(n->Left) || isArrayLiteralExpression(n->Left)) && ::tsc::containsObjectRestOrSpread(n->Left)) {
	facts |= SubtreeContainsObjectRestOrSpread;
	}
	}
	return facts;
}

