inline SubtreeFacts computeSubtreeFacts_Token(const Token* n) {
	switch (n->kind) {
	case Kind::UsingKeyword:
	return SubtreeContainsUsing;
	case Kind::PublicKeyword: case Kind::PrivateKeyword: case Kind::ProtectedKeyword: case Kind::ReadonlyKeyword: case Kind::AbstractKeyword: case Kind::DeclareKeyword: case Kind::ConstKeyword: case Kind::AnyKeyword: case Kind::NumberKeyword: case Kind::BigIntKeyword: case Kind::NeverKeyword: case Kind::ObjectKeyword: case Kind::InKeyword: case Kind::OutKeyword: case Kind::OverrideKeyword: case Kind::StringKeyword: case Kind::BooleanKeyword: case Kind::SymbolKeyword: case Kind::VoidKeyword: case Kind::UnknownKeyword: case Kind::UndefinedKeyword: case Kind::ExportKeyword:
	return SubtreeContainsTypeScript;
	case Kind::AccessorKeyword:
	return SubtreeContainsClassFields;
	case Kind::AsyncKeyword:
	return SubtreeContainsAnyAwait;
	case Kind::SuperKeyword:
	return SubtreeContainsLexicalSuper;
	case Kind::ThisKeyword:
	return SubtreeContainsLexicalThis;
	case Kind::AsteriskAsteriskToken: case Kind::AsteriskAsteriskEqualsToken:
	return SubtreeContainsExponentiationOperator;
	case Kind::QuestionQuestionToken:
	return SubtreeContainsNullishCoalescing;
	case Kind::QuestionDotToken:
	return SubtreeContainsOptionalChaining;
	case Kind::QuestionQuestionEqualsToken: case Kind::BarBarEqualsToken: case Kind::AmpersandAmpersandEqualsToken:
	return SubtreeContainsLogicalAssignments;
	}
	return SubtreeFactsNone;
}

