inline SubtreeFacts computeSubtreeFacts_VariableDeclaration(const VariableDeclaration* n) {
	return ::tsc::propagateSubtreeFacts(n->name) | propagateEraseableSyntaxSubtreeFacts(n->ExclamationToken) | propagateEraseableSyntaxSubtreeFacts(n->Type) | ::tsc::propagateSubtreeFacts(n->Initializer);
}

inline SubtreeFacts computeSubtreeFacts_VariableDeclarationList(const VariableDeclarationList* n) {
	return ::tsc::propagateNodeListSubtreeFacts(n->Declarations, propagateSubtreeFacts) | ifElse((n->flags&NodeFlagsUsing) != 0, SubtreeContainsUsing, SubtreeFactsNone);
}

inline SubtreeFacts computeSubtreeFacts_VariableStatement(const VariableStatement* n) {
	if (n->modifiers != nullptr && ((n->modifiers ? n->modifiers->ModifierFlags : ModifierFlags{})&ModifierFlagsAmbient) != 0) {
	return SubtreeContainsTypeScript;
	} else {
	return ::tsc::propagateModifierListSubtreeFacts(n->modifiers) | ::tsc::propagateSubtreeFacts(n->DeclarationList);
	}
}

inline SubtreeFacts computeSubtreeFacts_VoidExpression(const VoidExpression* n) {
	return ::tsc::propagateSubtreeFacts(n->Expression);
}

inline SubtreeFacts computeSubtreeFacts_WhileStatement(const WhileStatement* n) {
	return ::tsc::propagateSubtreeFacts(n->Expression) | ::tsc::propagateSubtreeFacts(n->Statement);
}

inline SubtreeFacts computeSubtreeFacts_WithStatement(const WithStatement* n) {
	return ::tsc::propagateSubtreeFacts(n->Expression) | ::tsc::propagateSubtreeFacts(n->Statement);
}

inline SubtreeFacts computeSubtreeFacts_YieldExpression(const YieldExpression* n) {
	return ::tsc::propagateSubtreeFacts(n->Expression) | SubtreeContainsForAwaitOrAsyncGenerator;
}

